const item = $input.item.json;

// Clean email: remove extra spaces and lowercase it.
const cleanEmail = String(item.rawEmail || "")
  .trim()
  .toLowerCase();

// Keep digits only for phone normalization.
const digits = String(item.rawPhone || "")
  .replace(/\D/g, "");

let cleanPhone = null;

// Assumption: 10-digit numbers are US/Canada-style numbers.
if (digits.length === 10) {
  cleanPhone = `+1${digits}`;
} else if (digits.length === 11 && digits.startsWith("1")) {
  cleanPhone = `+${digits}`;
} else if (
  String(item.rawPhone || "").trim().startsWith("+") &&
  digits.length >= 8 &&
  digits.length <= 15
) {
  cleanPhone = `+${digits}`;
}

return {
  json: {
    ...item,
    cleanEmail,
    cleanPhone
  }
};

const item = $input.item.json;

const disposableDomains = [
  "mailinator.com",
  "tempmail.com",
  "10minutemail.com",
  "throwaway.io"
];

const errors = [];

// Basic email structure validation.
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!item.cleanEmail || !emailRegex.test(item.cleanEmail)) {
  errors.push("INVALID_EMAIL_SYNTAX");
} else {
  const domain = item.cleanEmail.split("@")[1].toLowerCase();

  if (disposableDomains.includes(domain)) {
    errors.push("DISPOSABLE_EMAIL_DOMAIN_REJECTED");
  }
}

// Ensure a phone number was normalized.
if (!item.cleanPhone) {
  errors.push("INVALID_OR_MISSING_E164_PHONE");
}

return {
  json: {
    ...item,
    isQualityLead: errors.length === 0,
    validationErrors: errors
  }
};

const item = $input.item.json;

return {
  json: {
    quarantineStatus: "REJECTED_DEFECTIVE_INPUT",
    leadId: item.leadId,
    email: item.cleanEmail,
    errors: item.validationErrors,
    lead: item,
    rejectedAt: new Date().toISOString()
  }
};

const items = $input.all();
const seenFingerprints = new Set();

return items.map((inputItem) => {
  const item = inputItem.json;

  // Create a fingerprint using normalized email and phone.
  const fingerprint = `${item.cleanEmail}|${item.cleanPhone}`;

  const isDuplicate = seenFingerprints.has(fingerprint);

  if (!isDuplicate) {
    seenFingerprints.add(fingerprint);
  }

  return {
    json: {
      ...item,
      leadFingerprint: fingerprint,
      isDuplicate
    }
  };
});

const item = $input.item.json;

return {
  json: {
    quarantineStatus: "BYPASSED_DUPLICATE_LEAD",
    leadId: item.leadId,
    email: item.cleanEmail,
    leadFingerprint: item.leadFingerprint,
    quarantinedAt: new Date().toISOString()
  }
};

const items = $input.all();

return [
  {
    json: {
      pipelineSummary: "CLEAN_LEADS_INGESTED",
      uniqueLeadsPushed: items.length,
      executionTime: new Date().toISOString()
    }
  }
];
